          "caption": "Полная программа · C++20 · main.cpp",
          "code": "#include <cstdint>\n#include <iostream>\n#include <limits>\n#include <mutex>\n#include <string>\n#include <utility>\n\nstruct Task {\n    std::string title;\n    bool done;\n    std::uint64_t version;\n};\nenum class Update { applied, invalid, stale, exhausted };\n\nconst char* to_string(Update result) {\n    switch (result) {\n        case Update::applied: return \"applied\";\n        case Update::invalid: return \"invalid\";\n        case Update::stale: return \"stale\";\n        case Update::exhausted: return \"exhausted\";\n    }\n    return \"unknown\";\n}\n\nclass Store {\n    std::mutex mutex_;\n    Task task_{\"A\", false, 7};\npublic:\n    Task read() {\n        std::lock_guard lock(mutex_);\n        return task_;\n    }\n    Update replace(std::uint64_t expected, std::string title, bool done) {\n        if (title.empty() || title.size() > 40) return Update::invalid;\n        std::lock_guard lock(mutex_);\n        if (task_.version != expected) return Update::stale;\n        if (task_.version == std::numeric_limits<std::uint64_t>::max())\n            return Update::exhausted;\n        Task next{std::move(title), done, task_.version + 1};\n        task_.title.swap(next.title);\n        task_.done = next.done;\n        task_.version = next.version;\n        return Update::applied;\n    }\n};\n\nvoid print(const Task& task) {\n    std::cout << task.title << ' ' << task.done << \" v\" << task.version << '\\n';\n}\n\nint main() {\n    std::cout << std::boolalpha;\n    Store store;\n    auto x = store.read();\n    auto y = store.read();\n    auto first = store.replace(x.version, \"B\", x.done);\n    std::cout << \"X: \" << to_string(first) << '\\n';\n    auto second = store.replace(y.version, y.title, true);\n    std::cout << \"Y: \" << to_string(second) << '\\n';\n    print(store.read());\n    auto fresh = store.read();\n    auto retry = store.replace(fresh.version, fresh.title, true);\n    std::cout << \"Y after review: \" << to_string(retry) << '\\n';\n    auto bad = store.replace(9, \"\", false);\n    std::cout << \"bad: \" << to_string(bad) << '\\n';\n    auto repeat_x = store.replace(x.version, \"B\", x.done);\n    std::cout << \"repeat X: \" << to_string(repeat_x) << '\\n';\n    print(store.read());\n}\n"
